--
-- Table structure for table `order`
--

DROP TABLE IF EXISTS `order`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `order` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `userId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('PENDING','CONFIRMED','SHIPPING','DELIVERED','CANCELLED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING',
  `totalAmount` decimal(65,30) NOT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  `isGift` tinyint(1) NOT NULL DEFAULT '0',
  `message` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `paymentMethod` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `paymentStatus` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'UNPAID',
  `recipientAddress` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `recipientName` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `recipientPhone` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `shippingFee` decimal(65,30) NOT NULL DEFAULT '0.000000000000000000000000000000',
  `voucherId` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `shippingOrderCode` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `shippingProvider` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT 'GHN',
  `districtId` int DEFAULT NULL,
  `provinceId` int DEFAULT NULL,
  `wardCode` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `Order_userId_fkey` (`userId`),
  KEY `Order_voucherId_fkey` (`voucherId`),
  CONSTRAINT `Order_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `user` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `Order_voucherId_fkey` FOREIGN KEY (`voucherId`) REFERENCES `voucher` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

