  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  `images` json NOT NULL,
  `attributes` json DEFAULT NULL,
  `categoryId` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `originalPrice` decimal(15,2) DEFAULT NULL,
  `rating` double NOT NULL DEFAULT '0',
  `salesCount` int NOT NULL DEFAULT '0',
  `rejectReason` text COLLATE utf8mb4_unicode_ci,
  `status` enum('DRAFT','PENDING','ACTIVE','REJECTED','HIDDEN') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING',
  `shopId` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `shopCategoryId` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
