  KEY `Product_categoryId_price_idx` (`categoryId`,`price`),
  KEY `Product_name_createdAt_idx` (`name`,`createdAt` DESC),
  KEY `Product_sellerId_createdAt_idx` (`sellerId`,`createdAt` DESC),
  KEY `Product_shopId_idx` (`shopId`),
  KEY `Product_shopCategoryId_fkey` (`shopCategoryId`),
  KEY `Product_brandId_fkey` (`brandId`),
  CONSTRAINT `Product_brandId_fkey` FOREIGN KEY (`brandId`) REFERENCES `brand` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `Product_categoryId_fkey` FOREIGN KEY (`categoryId`) REFERENCES `category` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
