Sản phẩm có được bảo hành không?\\\":\\\"Không\\\",\\\"Thương hiệu\\\":\\\"CAVARA\\\",\\\"Xuất xứ thương hiệu\\\":\\\"Trung Quốc\\\",\\\"Xuất xứ (Made in)\\\":\\\"Trung Quốc\\\",\\\"videos\\\":[],\\\"sizeChart\\\":null,\\\"brand\\\":\\\"CAVARA\\\",\\\"origin\\\":\\\"Vietnam\\\",\\\"weight\\\":200,\\\"dimensions\\\":{\\\"length\\\":10,\\\"width\\\":10,\\\"height\\\":5}}\"',NULL,NULL,0,0,NULL,'ACTIVE','69650d66-843d-4850-a6c5-3d27e8aeec03',NULL,NULL,NULL,200);
