  `slug` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `avatar` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `coverImage` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pickupAddress` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('ACTIVE','PENDING','BANNED','REJECTED','VACATION') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING',
  `banReason` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `decoration` json DEFAULT NULL,
