  `businessLicenseBack` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `businessLicenseFront` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `distributorCert` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `salesLicense` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `trademarkCert` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pendingDetails` json DEFAULT NULL,
  `districtId` int DEFAULT NULL,
  `lat` double DEFAULT '0',
  `lng` double DEFAULT '0',
  `provinceId` int DEFAULT NULL,
  `wardCode` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `Shop_slug_key` (`slug`),
  UNIQUE KEY `Shop_ownerId_key` (`ownerId`),
  KEY `Shop_name_idx` (`name`),
  KEY `Shop_status_idx` (`status`),
  CONSTRAINT `Shop_ownerId_fkey` FOREIGN KEY (`ownerId`) REFERENCES `user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
